package com.xjtu.iron.idempotent.api;
/** requestHash 防止同一个幂等 Key 被不同请求参数复用。 */
public final class IdempotencyRequest{private final String key,requestHash;private final IdempotencyOptions options;private IdempotencyRequest(Builder b){key=b.key;requestHash=b.requestHash;options=b.options;}public static Builder builder(){return new Builder();}public static IdempotencyRequest of(String key,IdempotencyOptions options){return builder().key(key).options(options).build();}public String getKey(){return key;}public String getRequestHash(){return requestHash;}public IdempotencyOptions getOptions(){return options;}public static final class Builder{private String key,requestHash;private IdempotencyOptions options;public Builder key(String v){key=v;return this;}public Builder requestHash(String v){requestHash=v;return this;}public Builder options(IdempotencyOptions v){options=v;return this;}public IdempotencyRequest build(){return new IdempotencyRequest(this);}}}
